1	/* See stack.h. Builds the stack top-down: strings first (highest
2	 * addresses), then the block of auxv/envp/argv/argc. That block's size is
3	 * NOT fixed once argv has more than one entry (ROADMAP_LINUX_RUNTIME.md
4	 * U8): 14 auxv pairs (224 bytes, always) + envp NULL (8) + (argc+1)*8
5	 * (argv pointers + NULL) + argc (8) is a multiple of 16 only for odd argc
6	 * (e.g. argc==1: 224+8+16+8=256). For even argc it is 8 mod 16, so an
7	 * extra 8-byte pad word is inserted between the strings and this block
8	 * whenever needed -- computed from the REAL argc, not assumed -- so the
9	 * final sp (== &argc, the last thing written) is always 16-byte aligned,
10	 * per the RISC-V psABI requirement at a function entry (exactly how the
11	 * app's entry point is reached, main.c's asm trampoline).
12	 */
13	#include "stack.h"
14	
15	#include <elf.h>
16	#include <string.h>
17	
18	#include "manifest.h"
19	
20	#define STACK_RESERVE (8ull * 1024 * 1024) /* top 8 MiB of RAM (roadmap) */
21	
22	struct writer {
23	  char* p; /* next push lands just BELOW this (stack grows down) */
24	};
25	
26	static char* push_bytes(struct writer* w, const void* src, size_t len)
27	{
28	  w->p -= len;
29	  memcpy(w->p, src, len);
30	  return w->p;
31	}
32	
33	static void align_down(struct writer* w, size_t align)
34	{
35	  w->p = (char*) ((uintptr_t) w->p & ~(align - 1));
36	}
37	
38	/* AT_HWCAP: one bit per ISA letter present, bit = letter - 'A' (the RISC-V
39	 * Linux convention; see arch/riscv/kernel/cpufeature.c). Computed rather
40	 * than a magic number, so the extension set stays self-documenting. */
41	static unsigned long hwcap_imafdcv(void)
42	{
43	  unsigned long h = 0;
44	  for (const char* c = "IMAFDCV"; *c; ++c) h |= 1ul << (*c - 'A');
45	  return h;
46	}
47	
48	/* 16 bytes of AT_RANDOM filler. Not a security boundary here (simulator);
49	 * mcycle-seeded like ROADMAP_LINUX_RUNTIME.md U4's planned getrandom, so a
50	 * glibc stack-protector canary is at least not predictable all-zero. Reads
51	 * the M-mode CSR (mcycle, 0xB00) directly, NOT the rdcycle/rdtime pseudo-ops
52	 * -- those target the UNPRIVILEGED shadow CSRs (0xC00/0xC01, optional
53	 * Zicntr), which the real RTL does not implement and traps on; mcycle is
54	 * mandatory in M-mode on every engine. */
55	static void fill_random16(unsigned char out[16])
56	{
57	  unsigned long a;
58	  asm volatile("csrr %0, mcycle" : "=r"(a));
59	  const unsigned long b = a ^ 0x9e3779b97f4a7c15ul; /* golden-ratio mix */
60	  for (int i = 0; i < 8; ++i) {
61	    out[i] = (unsigned char) (a >> (8 * i));
62	    out[8 + i] = (unsigned char) (b >> (8 * i));
63	  }
64	}
65	
66	uintptr_t build_initial_stack(const char* app_path, uint64_t mem_size,
67	                              const struct loaded_elf* elf,
68	                              const char* extra_argv_buf,
69	                              uint32_t extra_argv_count)
70	{
71	  struct writer w;
72	  /* Start at the true top of RAM, not at mem_size - STACK_RESERVE: that
73	   * offset is the FLOOR the stack must stay above (mm.c's mmap arena starts
74	   * there and grows further down) -- starting the build AT the floor would
75	   * push this content below it immediately, into the mmap arena's own
76	   * territory (found via a real collision: the app's first sizeable mmap
77	   * landed exactly on top of its own live stack and zeroed it). The
78	   * reserved 8 MiB between here and the floor is the app's headroom to
79	   * grow into during execution, not space this initial build should use. */
80	  w.p = (char*) (uintptr_t) mem_size;
81	
82	  /* Strings: app_path (argv[0] / AT_EXECFN), then each extra arg
83	   * (argv[1..]), then AT_RANDOM's bytes -- capturing every argv pointer
84	   * as we go, since the pointer array below is built AFTER all strings
85	   * (it needs every address up front). */
86	  const uint32_t argc = 1 + extra_argv_count;
87	  char* argv_ptrs[1 + VLINUX_MANIFEST_ARGV_MAX_COUNT];
88	  argv_ptrs[0] = push_bytes(&w, app_path, strlen(app_path) + 1);
89	  const char* p = extra_argv_buf;
90	  for (uint32_t i = 0; i < extra_argv_count; ++i) {
91	    const size_t n = strlen(p) + 1;
92	    argv_ptrs[1 + i] = push_bytes(&w, p, n);
93	    p += n;
94	  }
95	  unsigned char rnd[16];
96	  fill_random16(rnd);
97	  char* at_random = push_bytes(&w, rnd, sizeof(rnd));
98	
99	  /* The block below is 14 auxv pairs (224) + envp NULL (8) +
100	   * (argc+1)*8 argv slots + argc (8) -- a multiple of 16 only for odd
101	   * argc. align_down alone assumed a fixed 256-byte block (true only for
102	   * argc==1); for the general case, drop one more pad word whenever the
103	   * real block size is 8 mod 16, so the block's END (== final sp) lands
104	   * 16-aligned regardless of argc. */
105	  const size_t block_size = 224 + 8 + (size_t) (argc + 1) * 8 + 8;
106	  align_down(&w, 16);
107	  w.p -= (16 - (block_size % 16)) % 16;
108	
109	#define AUX(t, v)                                                          \
110	  do {                                                                     \
111	    long pair[2] = {(long) (t), (long) (uintptr_t) (v)};                   \
112	    push_bytes(&w, pair, sizeof(pair));                                    \
113	  } while (0)
114	
115	  /* Pushed high-to-low, so the FIRST push (AT_NULL) ends up at the highest
116	   * address -- i.e. last when the app scans forward from the final sp. */
117	  AUX(AT_NULL, 0);
118	  AUX(AT_EXECFN, argv_ptrs[0]);
119	  AUX(AT_SECURE, 0);
120	  AUX(AT_EGID, 0);
121	  AUX(AT_GID, 0);
122	  AUX(AT_EUID, 0);
123	  AUX(AT_UID, 0);
124	  AUX(AT_HWCAP, hwcap_imafdcv());
125	  AUX(AT_RANDOM, at_random);
126	  AUX(AT_ENTRY, elf->entry);
127	  AUX(AT_PAGESZ, 4096);
128	  AUX(AT_PHNUM, elf->phnum);
129	  AUX(AT_PHENT, elf->phentsize);
130	  AUX(AT_PHDR, elf->phdr_vaddr);
131	#undef AUX
132	
133	  long envp_null = 0;
134	  push_bytes(&w, &envp_null, sizeof(envp_null));
135	
136	  long argv_null = 0;
137	  push_bytes(&w, &argv_null, sizeof(argv_null));
138	  /* Reverse order: argv[argc-1]'s pointer pushed first (highest address
139	   * among the argv slots), argv[0]'s pointer pushed LAST -- landing right
140	   * above argc, exactly the layout a Linux process expects reading
141	   * forward from its initial sp: argc, argv[0], argv[1], ..., NULL. */
142	  for (uint32_t i = argc; i-- > 0;) {
143	    long ptr = (long) (uintptr_t) argv_ptrs[i];
144	    push_bytes(&w, &ptr, sizeof(ptr));
145	  }
146	
147	  long argc_val = (long) argc;
148	  push_bytes(&w, &argc_val, sizeof(argc_val));
149	
150	  return (uintptr_t) w.p;
151	}
